#include <atomic>
#include <thread>
#include <vector>

std::atomic<long> counts[4];          // 4 x 8 bytes = 32 bytes, contiguous

void worker(int id, long n) {
    for (long i = 0; i < n; ++i)
        counts[id].fetch_add(1, std::memory_order_relaxed);  // only my slot
}

int main() {
    std::vector<std::thread> ts;
    for (int id = 0; id < 4; ++id) ts.emplace_back(worker, id, 500'000'000L);
    for (auto& t : ts) t.join();
}

// Fix 1: keep the hot loop's writes private, publish once.
void worker(int id, long n) {
    long local = 0;                 // lives in a register
    for (long i = 0; i < n; ++i)
        ++local;
    counts[id].store(local, std::memory_order_relaxed);  // one shared write
}

